import json,subprocess,sys,os,time,datetime,hashlib
from pathlib import Path
trial,out=map(Path,sys.argv[1:]);deadline=time.monotonic()+7200

def state(status,**fields):
 value=dict(status=status,pid=os.getpid(),checked_at=datetime.datetime.now().astimezone().isoformat(),**fields)
 tmp=out/'PIPELINE.json.tmp';tmp.write_text(json.dumps(value,indent=2)+'\n');tmp.replace(out/'PIPELINE.json')
def sha(path):
 h=hashlib.sha256()
 with path.open('rb') as f:
  while chunk:=f.read(8*1024*1024):h.update(chunk)
 return h.hexdigest()
try:
 state('waiting_for_matched_500_training')
 while True:
  pipeline=json.loads((trial/'PIPELINE.json').read_text())
  if pipeline['status']=='failed':raise RuntimeError('Training pipeline failed: '+str(pipeline))
  if pipeline['status']=='completed':break
  if time.monotonic()>deadline:raise TimeoutError('Training not complete within two hours')
  time.sleep(15)
 audit=json.loads((trial/'MATCHED_AUDIT.json').read_text())
 assert audit['updates_per_arm']==500, audit
 (out/'checkpoints').mkdir(exist_ok=True)
 models={}
 for arm,arch in [('control','original'),('attention','scene_cross_attention')]:
  status=json.loads((trial/arm/'STATUS.json').read_text());assert status['step']==500
  original=trial/arm/'training/last.pt';pinned=out/'checkpoints'/(arm+'500.pt')
  assert not pinned.exists();os.link(original,pinned)
  checksum=sha(pinned);assert checksum==status['checkpoint_sha256']
  models[arm+'500']=dict(checkpoint=str(pinned),checkpoint_sha256=checksum,expected_step=500,architecture=arch,arms=['none','learned_only'])
 (out/'MODELS.json').write_text(json.dumps(models,indent=2)+'\n')
 base=[sys.executable,'-u','-m','experiments.offline_camera_retrain_v1.ops.ego_scene_review']
 commands=[base+['prepare','--out',str(out),'--models',str(out/'MODELS.json')],base+['evaluate','--out',str(out)],base+['recheck','--out',str(out)]]
 (out/'COMMANDS.json').write_text(json.dumps(commands,indent=2)+'\n')
 for i,args in enumerate(commands):
  state('running',command_index=i,argv=args)
  with (out/('job_%02d.log'%i)).open('ab') as log:subprocess.run(args,stdin=subprocess.DEVNULL,stdout=log,stderr=subprocess.STDOUT,check=True)
 state('completed',commands_completed=len(commands))
except BaseException as exc:
 state('failed',error=repr(exc));raise
